	if 'id' in value:
		self.params.selectId = int(value['id'])

		page = kanoa.page.formatId(self.page.props.pageId)
		for key in value.keys():
			if key != 'id':
				if key == 'dates':
					dates = system.util.jsonDecode(value['dates'])
					self.session.custom.pages[page].filters['dates']['startDate'] = system.date.parse(dates['startDate'], "MM/DD/yyyy HH:mm:ss")
					self.session.custom.pages[page].filters['dates']['endDate'] = system.date.parse(dates['endDate'], "MM/DD/yyyy HH:mm:ss")
					self.session.custom.pages[page].filters['dates']['selectedRange'] = dates['selectedRange']

#				elif key == 'shift':
				else:
					filterValue = system.util.jsonDecode(str(value[key]))
					if "str" in str(type(filterValue)):
						self.session.custom.pages[page].filters['shift'] = filterValue.replace('"', '')
					else:
						self.session.custom.pages[page].filters['shift'] = filterValue

		return value['id'], value.keys(), value.values(), [str(type(system.util.jsonDecode(x))) for x in value.values()]

userId = value['security']['userId'] or -1
if userId == -1: userId = system.kanoa.security.getIDPUserId({'userName': 'GUEST'})
return system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.dashboard.getUserDashboards({'userId': userId, 'dashboardId': value['dashboardId'] or -1}),0)
